// 나쁜 예: setTimeout은 프레임과 싱크가 안 맞음
let box1 = 0;
function badAni() {
  box1 += 1;
  // 60fps보다 빠르거나 느리게 실행될 수 있음 (Jank 유발)
  setTimeout(badAni, 10);
}

// 좋은 예: rAF는 화면 주사율에 딱 맞춤
let box2 = 0;
function goodAni() {
  box2 += 1;
  // 브라우저: "다음 그림 그리기 직전에 불러줄게!"
  requestAnimationFrame(goodAni);
}

requestAnimationFrame(goodAni);
